 public const string Success = """<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Spectra — вход выполнен</title><style>@font-face{font-family:SpectraPixel;src:url(data:font/ttf;base64,) format('truetype')}@font-face{font-family:SpectraReading;src:url(data:font/ttf;base64,) format('truetype')}*{box-sizing:border-box}html,body{margin:0;height:100%}body{display:grid;place-items:center;padding:24px;overflow:hidden;color:#edf3fc;color-scheme:dark;font-family:SpectraReading,'Segoe UI',sans-serif;font-size:14px;background:radial-gradient(ellipse at 18% 0%,#26435440,transparent 55%),radial-gradient(ellipse at 85% 95%,#1b413b30,transparent 50%),#091119}body:before{content:'';position:fixed;inset:0;pointer-events:none;background-image:linear-gradient(#a7d6ef0a 1px,transparent 1px),linear-gradient(90deg,#a7d6ef0a 1px,transparent 1px);background-size:32px 32px}.ambient{position:fixed;pointer-events:none;border-radius:50%;filter:blur(100px);opacity:.25}.ambient.a{background:#2868c8;width:600px;height:600px;top:-400px;left:12%}.ambient.b{background:#5e45af;width:600px;height:600px;bottom:-470px;right:-100px}.card{position:relative;width:100%;max-width:460px;padding:44px 40px 36px;text-align:center;border-radius:19px;background:linear-gradient(135deg,#ffffff0f,#ffffff03),#111b2ad9;border:1px solid #ffffff20;box-shadow:inset 0 1px 0 #ffffff18,0 20px 70px #0006;animation:appear .45s both}.card:before{content:'';position:absolute;width:260px;height:260px;right:-80px;top:-150px;transform:rotate(28deg);border:1px solid #d8edff26;border-radius:40px;background:linear-gradient(140deg,#badcff0c,#b2cfff02);pointer-events:none}@keyframes appear{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}.brand{display:flex;align-items:center;justify-content:center;gap:12px;margin-bottom:30px;font-family:SpectraPixel,Consolas,monospace;font-size:12px;letter-spacing:3px;color:#8694ab}.brand i{width:30px;height:30px;background:#b7d7fc;-webkit-mask:url(data:image/png;base64,) center/contain no-repeat;mask:url(data:image/png;base64,) center/contain no-repeat;filter:drop-shadow(0 0 12px #8cc9ff66)}.badge{width:78px;height:78px;margin:0 auto 24px;display:grid;place-items:center;border-radius:20px;font-size:38px;font-family:SpectraPixel,Consolas,monospace}.ok .badge{background:linear-gradient(145deg,#a4cbe62b,#7bb89b22);border:1px solid #b4decd66;color:#b4decd;box-shadow:0 0 40px #7bb89b30}.bad .badge{background:linear-gradient(145deg,#e6a4a42b,#b33b5022);border:1px solid #e6919166;color:#f0a3ad;box-shadow:0 0 40px #b33b5030}.eyebrow{font-family:SpectraPixel,Consolas,monospace;font-size:10px;letter-spacing:3px;color:#8ba3be;margin-bottom:12px}h1{margin:0;font-family:SpectraPixel,Consolas,monospace;font-weight:600;font-size:34px;letter-spacing:-.5px;color:#edf3fc}p{color:#8e9db3;line-height:1.65;margin:14px 0 0;font-size:14px}.line{height:1px;margin:28px auto 22px;width:200px;background:linear-gradient(90deg,transparent,#c3dbff44,transparent)}button{font:inherit;cursor:pointer;color:#122742;font-family:SpectraPixel,Consolas,monospace;font-size:13px;padding:12px 26px;border-radius:10px;border:1px solid #d0e9ff80;background:linear-gradient(130deg,#d0e9ff,#9fc8f3);box-shadow:0 0 24px #88bfff14;transition:transform .18s,background .18s}button:hover{background:linear-gradient(130deg,#e4f2ff,#badfff)}button:active{transform:scale(.97)}.hint{display:block;margin-top:16px;line-height:1.6;font-size:11px;color:#637892;letter-spacing:.5px}@media(prefers-reduced-motion:reduce){.card{animation:none}}</style></head><body><div class="ambient a"></div><div class="ambient b"></div><main class="card ok"><div class="brand"><i></i>SPECTRA</div><div class="badge">✓</div><div class="eyebrow">АККАУНТ ПОДКЛЮЧЁН</div><h1>ГОТОВО</h1><p>Вы зарегистрировались, доступ подтверждён. Вернитесь в Spectra — лаунчер уже продолжает работу.</p><div class="line"></div><button onclick="window.close()">За